fn check_disconnected(
    _n: i8,
    _m: i8,
    horizontal: &Vec<char>,
    vertical: &Vec<char>,
) -> bool {
    // We only care about the four corner arrows:
    // horizontal[0], horizontal[n-1], vertical[0], vertical[m-1]
    let first_h = horizontal[0];
    let last_h = horizontal[horizontal.len() - 1];
    let first_v = vertical[0];
    let last_v = vertical[vertical.len() - 1];

    // The configuration is "disconnected" if and only if at least one of:
    // 1) first_h == '>' and first_v == 'v'
    // 2) first_h == '<' and last_v  == 'v'
    // 3) last_h  == '>' and first_v == '^'
    // 4) last_h  == '<' and last_v  == '^'
    (first_h == '>' && first_v == 'v')
        || (first_h == '<' && last_v == 'v')
        || (last_h == '>' && first_v == '^')
        || (last_h == '<' && last_v == '^')
}

fn solve(
    n: i8,
    m: i8,
    horizontal: Vec<char>,
    vertical: Vec<char>,
) -> Vec<char> {
    if check_disconnected(n, m, &horizontal, &vertical) {
        vec!['N', 'O', '\n']
    } else {
        vec!['Y', 'E', 'S', '\n']
    }
}